chrome.runtime.onInstalled.addListener(()=>{console.log("NOCAP Extension installed (v1.5.0)!")});chrome.runtime.onMessage.addListener((r,o,t)=>{if(r.action==="PING")t({success:!0});else if(r.action==="FETCH_WIKI"){const u=encodeURIComponent(r.query||"");return fetch(`https://ko.wikipedia.org/w/api.php?action=query&format=json&prop=extracts&exintro=true&explaintext=true&titles=${u}&origin=*`).then(e=>e.json()).then(e=>{const n=e?.query?.pages;if(!n)return t({result:null});const i=Object.keys(n)[0];t(i==="-1"?{result:null}:{result:n[i].extract.substring(0,500)})}).catch(e=>t({result:null})),!0}return!0});
